public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int n = scanner.nextInt();

    String gridA[][] = new String[n][n];
    String gridB[][] = new String[n][n];

    for (int i = 0; i < n; i++) {
        String text = scanner.next();
        gridA[i] = text.split("");
    }

    for (int i = 0; i < n; i++) {
        String text = scanner.next();
        gridB[i] = text.split("");
    }

    scanner.close();

    int differingRow = -1;
    int differingCol = -1;

    outerLoop:
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (!gridA[i][j].equals(gridB[i][j])) {
                differingRow = i + 1;
                differingCol = j + 1;
                break outerLoop;
            }
        }
    }

    System.out.println(differingRow + " " + differingCol);
}
